import { useParams } from "react-router-dom";
import productData from "../data/product.json";

export default function AdminEditProduct() {
  const { id } = useParams();
  const product = productData.find((p) => p.id === Number(id));

  if (!product) return <h1>Product Not Found</h1>;

  return (
    <div className="admin-page">
      <h1>Edit Product #{id}</h1>

      <form className="admin-form">
        <label>Product Name</label>
        <input type="text" defaultValue={product.name} />

        <label>Variation</label>
        <input type="text" defaultValue={product.category} />

        <label>Price</label>
        <input type="number" defaultValue={product.price} />

        <label>Description</label>
        <textarea defaultValue={product.description} />

        <label>Image</label>
        <input type="file" />

        <button className="orange-btn">Update Product</button>
      </form>
    </div>
  );
}
